                'name' => 'LIST 2 (PLASTIC, BURNS & AESTHETIC SURGERY TREATMENTS / MANAGEMENT  OPTIONS)  Plastic, Burns & Aesthetic   Acute Burn Management (Fluid Resuscitation, Wound Care & Infection Control)',
                'slug' => Str::slug('LIST 2 (PLASTIC, BURNS & AESTHETIC SURGERY TREATMENTS / MANAGEMENT  OPTIONS)  Plastic, Burns & Aesthetic   Acute Burn Management (Fluid Resuscitation, Wound Care & Infection Control)'),
                'h1' => 'LIST 2 (PLASTIC, BURNS & AESTHETIC SURGERY TREATMENTS / MANAGEMENT  OPTIONS)  Plastic, Burns & Aesthetic   Acute Burn Management (Fluid Resuscitation, Wound Care & Infection Control)',
                'icon' => null,
